# This file configures the latexmk command you can use to compile
# the pdf version of the blueprint
$pdf_mode = 1;
$pdflatex = 'xelatex -synctex=1';
@default_files = ('print.tex');% This file makes a printable version of the blueprint
% It should include all the \usepackage needed for the pdf version.
% The template version assume you want to use a modern TeX compiler
% such as xeLaTeX or luaLaTeX including support for unicode
% and Latin Modern Math font with standard bugfixes applied.
% It also uses expl3 in order to support macros related to the dependency graph.
% It also includes standard AMS packages (and their improved version
% mathtools) as well as support for links with a sober decoration
% (no ugly rectangles around links).
% It is otherwise a very minimal preamble (you should probably at least
% add cleveref and tikz-cd).

\documentclass[a4paper]{report}

\usepackage{geometry}

\usepackage{expl3}

\usepackage{amssymb, amsthm, mathtools}
\usepackage[unicode,colorlinks=true,linkcolor=blue,urlcolor=magenta, citecolor=blue]{hyperref}

\usepackage[warnings-off={mathtools-colon,mathtools-overbracket}]{unicode-math}

\input{macros/common}
\input{macros/print}

\title{AlgebraicJacobian}
\author{Axel Delaval
}

\begin{document}
\maketitle
\input{content}
\end{document}% Actual content of the blueprint, shared by the web and print versions.
% It must *not* include \begin{document}. Split content across chapters with \input.
%
% The refactor grows this file: each new mathematical chapter is a separate file under
% chapters/ and is added here in dependency order, mirroring the structure of the sources.

\input{chapters/Challenge}
\input{chapters/BaseChange}
\input{chapters/Curves}
\input{chapters/Algebra}
\input{chapters/Cohomology}
\input{chapters/RiemannRoch}
\input{chapters/PicardEtale}
\input{chapters/DivisorScheme}
\input{chapters/Tangent}
\input{chapters/AbelianVariety}
\input{chapters/Albanese}
\input{chapters/Jacobian}
